INSERT OR REPLACE INTO qr_evidence (id, evidence_type, provenance, locator, source_ref, content_text_ar, content_text, is_disputed, created_at, updated_at) VALUES
('QR:EV:40:7:s1:jadwal:1', 'irab_quote', 'الجدول في إعراب القرآن', '40:7', 'qul_jadwal_irab_quran', '(الواو) عاطفة في المواضع الخمسة (من) موصول في محلّ رفع معطوف على المبتدأ (الذين)، (حوله) ظرف منصوب متعلّق بمحذوف صلة من (بحمد) متعلّق بحال من فاعل يسبّحون (به) متعلّق ب (يؤمنون)، (للذين) متعلّق ب (يستغفرون). «الذين يحملون ...» لا محلّ لها استئنافيّة. «يحملون ...» لا محلّ لها صلة الموصول. «يسبّحون ...» في محلّ رفع خبر المبتدأ (الذين). «يؤمنون به ...» في محلّ رفع معطوفة على جملة يسبّحون. «يستغفرون ...» في محلّ رفع معطوفة على جملة يسبحون. «آمنوا ...» لا محلّ لها صلة الموصول (الذين) الثاني. وجملة النداء وجوابه ... في محلّ نصب مقول القول لقول مقدّر.. وجملة القول المقدّرة في محلّ نصب حال من فاعل يستغفرون', 'The wāws join; «man» is joined to the subject «alladhīna»; «ḥawlahu» belongs to the omitted relative clause of «man»; «bi-ḥamdi» belongs to a ḥāl of the subject of «yusabbiḥūna». The sentence is resumptive; «yusabbiḥūna» is the predicate, «yuʾminūna» and «yastaghfirūna» joined to it. The call and its answer are the speech of an understood «they say», itself a ḥāl of the subject of «yastaghfirūna».', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:daas:1', 'irab_quote', 'إعراب القرآن لدعاس', '40:7', 'qul_irab_quran_daas', 'الذين: مبتدأ. يحملون: مضارع مرفوع بثبوت النون والواو فاعله. العرش: مفعوله والجملة صلة. ومن: اسم موصول معطوف على الذين. حوله: ظرف مكان. يسبحون: مضارع مرفوع والواو فاعله والجملة خبر الذين. بحمد: متعلقان بيسبحون. ربهم: مضاف إليه. ويؤمنون: معطوف على يسبحون. به: متعلقان بيؤمنون. ويستغفرون: معطوف على ما قبله. للذين: متعلقان بيستغفرون. آمنوا: ماض وفاعله والجملة صلة.', 'Word by word: «alladhīna» subject; «yaḥmilūna al-ʿarsh» its relative clause; «man» joined to «alladhīna»; «ḥawlahu» an adverb of place; «yusabbiḥūna» the predicate; «bi-ḥamdi» attached to «yusabbiḥūna»; «yuʾminūna» and «yastaghfirūna» joined.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:muyassar:1', 'irab_quote', 'الإعراب الميسر', '40:7', 'qul_irab_muyassar', '﴿الذين﴾ مبتدأ ... و﴿من﴾ اسم موصول في محل رفع عطفا على المبتدأ، و﴿حوله﴾ ظرف متعلق بمحذوف صلة ﴿مَن﴾ ... و﴿بحمد﴾ جار ومجرور متعلقان بمحذوف حال، أي: ملابسين للحمد ... وجملة ﴿يسبحون بحمد ربهم﴾ خبر ﴿الذين﴾ ... و﴿يؤمنون﴾ عطف على ﴿يسبحون﴾. الواو عاطفة، و﴿يستغفرون﴾ ... و﴿ربنا﴾ منادى مضاف حذف منه حرف النداء، وجملة النداء مقول قول محذوف في محل نصب على الحال، أي: قائلين', '«bi-ḥamdi» belongs to an omitted ḥāl — «accompanied by praise»; «yusabbiḥūna bi-ḥamdi rabbihim» is the predicate; the call is the speech of an omitted «saying», in the accusative as a ḥāl.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:ukbari:1', 'irab_quote', 'التبيان في إعراب القرآن', '40:7', 'tibyan_ukbari_irab', '(الذين يحملون): مبتدأ، و«يسبحون»: خبره. (ربنا) أي يقولون، وهذا المحذوف حال.', '«Those who bear» is the subject and «they glorify» its predicate. «Our Lord» — that is, they say; this omitted verb is a ḥāl.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:ibn_ashur:1', 'tafsir_quote', 'التحرير والتنوير', '40:7', 'ibn_ashur', 'استئناف ابتدائي اقتضاه الانتقال من ذكر الوعيد المؤذن بذم الذين كفروا إلى الثناء على المؤمنين ... ويجوز أن يكون استئنافا بيانيا ... والإخبار عن صنفي الملائكة بأنهم يسبحون ويؤمنون به توطئة وتمهيد للإخبار عنهم بأنهم يستغفرون للذين آمنوا فذلك هو المقصود من الخبر ... وصيغة المضارع ... مفيدة لتجدد ذلك وتكرره ... وفائدة الإخبار عنهم بأنهم يؤمنون ... التنويه بشأن الإيمان ... والتعريض بالمشركين ... وجملة ﴿ربنا وسعت كل شيء رحمة وعلما﴾ مبينة ل (يستغفرون)، وفيها قول محذوف ... والباء في (بحمد ربهم) للملابسة ... فحذف مفعول (يسبحون) لدلالة المتعلق به عليه.', 'A fresh start turning from the threat to the disbelievers to praise of the believers (or a clarifying resumption). Their glorifying and believing prepare the real news — that they ask forgiveness for the believers; the present tense marks renewal; «they believe» honours faith and reproaches the idolaters; the prayer explains «yastaghfirūna», with a «saying» omitted; the bāʾ is of accompaniment, and the object of «yusabbiḥūna» is dropped because its complement shows it.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:zamakhshari:1', 'tafsir_quote', 'الكشاف', '40:7', 'zamakhshari', 'فائدته إظهار شرف الإيمان وفضله، والترغيب فيه ... وفائدة أخرى: وهي التنبيه على أن الأمر لو كان كما تقول المجسمة، لكان حملة العرش ومن حوله مشاهدين معاينين، ولما وصفوا بالإيمان ... وقد روعي التناسب في قوله ويؤمنون به ويستغفرون للذين آمنوا ... أى يقولون ربنا وهذا المضمر يحتمل أن يكون بيانا ليستغفرون مرفوع المحل مثله، وأن يكون حالا.', 'The point of «they believe in Him» is to show the honour of faith — and that the bearers do not see Him, or they would not be praised for belief. «They believe … for those who believe» keeps a congruence. «Our Lord» means «they say», the omitted verb either explaining «yastaghfirūna» (nominative like it) or a ḥāl.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:munayyir:1', 'tafsir_quote', 'الانتصاف (حاشية الكشاف)', '40:7', 'zamakhshari', 'كلام حسن إلا استدلاله بقوله ويؤمنون به على أنهم ليسوا مشاهدين، فهذا لا يدل، لأن الايمان هو التصديق غير مشروط فيه غيبة المصدق به', 'Ibn al-Munayyir, glossing al-Kashshāf: well said, except the inference that they do not see Him — belief is assent and does not require its object to be absent.', 1, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:tabari:1', 'tafsir_quote', 'جامع البيان', '40:7', 'tabari', 'وفي هذا الكلام محذوف، وهو يقولون؛ ومعنى الكلام ويستغفرون للذين آمنوا يقولون: يا ربنا وسعت كل شيء رحمة وعلما ... ﴿ويستغفرون للذين آمنوا﴾ لأهل لا اله إلا الله (قتادة).', 'There is an omission here, «they say»: they ask forgiveness for the believers, saying, «Our Lord…». Qatāda: «for those who believe» — the people of «there is no god but God».', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:razi:1', 'tafsir_quote', 'مفاتيح الغيب', '40:7', 'razi', 'ولا شك أن حامل العرش يكون حاملا لكل من في العرش، فلو كان إله العالم في العرش لكان هؤلاء الملائكة حاملين لإله العالم ... فالتسبيح إشارة إلى الجلال والتحميد إشارة إلى الإكرام ... فقوله: ﴿يسبحون بحمد ربهم ويؤمنون به﴾ مشعر بالتعظيم لأمر الله وقوله: ﴿ويستغفرون للذين آمنوا﴾ مشعر بالشفقة على خلق الله.', 'The bearer of the Throne bears whatever is on it, so the God of the worlds is not on the Throne. Glorifying points to majesty, praising to generosity; glorifying and believing show reverence for God''s command, asking forgiveness shows compassion for His creatures.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:EV:40:7:s1:ibn_kathir:1', 'tafsir_quote', 'تفسير القرآن العظيم', '40:7', 'ibn_kathir', 'يخبر تعالى عن الملائكة المقربين من حملة العرش الأربعة، ومن حوله من الكروبيين، بأنهم يسبحون بحمد ربهم، أي: يقرنون بين التسبيح الدال على نفي النقائص، والتحميد المقتضي لإثبات صفات المدح ... وهو يقتضي أن حملة العرش اليوم أربعة، فإذا كان يوم القيامة كانوا ثمانية', 'The angels brought near — the four bearers of the Throne and the karūbiyyūn around it — join glorification, which denies every flaw, to praise, which affirms every perfection. The bearers are four today and will be eight on the Day.', 0, '2026-10-15 18:00:00', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_scope_reading (id, scope_type, scope_id, scholar_ref, paradigm_ref, reading_type, reading_text, reading_text_ar, is_minority, is_contested, is_selected, witness_count, note_md, gloss_json, created_at, updated_at) VALUES
('QR:SR:40:7:s1:r1', 'sentence', 'QR:SS:40:7:jadwal:s1', 'qul_jadwal_irab_quran;ibn_ashur', 'jumhur', 'irab', 'A resumptive sentence with no place (al-Jadwal) — a fresh start (Ibn ʿĀshūr).', 'الجملة استئنافية لا محل لها (الجدول)، استئناف ابتدائي (ابن عاشور).', 0, 0, 1, 2, NULL, '{"ar": "الجملة استئنافية لا محل لها (الجدول)، استئناف ابتدائي (ابن عاشور).", "en": "A resumptive sentence with no place (al-Jadwal) — a fresh start (Ibn ʿĀshūr).", "ur": "مستانفہ جملہ، محل سے خالی (الجدول) — نیا آغاز (ابن عاشور)۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:r2', 'sentence', 'QR:SS:40:7:jadwal:s1', 'ibn_ashur', 'minority', 'irab', 'Ibn ʿĀshūr also allows a clarifying resumption — answering an unspoken question about those who do not dispute God''s signs.', 'ويجوز أن يكون استئنافًا بيانيًا جوابًا عن سؤال عن حال الذين لا يجادلون في آيات الله (ابن عاشور).', 1, 0, 0, 1, NULL, '{"ar": "ويجوز أن يكون استئنافًا بيانيًا جوابًا عن سؤال عن حال الذين لا يجادلون في آيات الله (ابن عاشور).", "en": "Ibn ʿĀshūr also allows a clarifying resumption — answering an unspoken question about those who do not dispute God''s signs.", "ur": "ابن عاشور یہ بھی جائز رکھتے ہیں کہ یہ استینافِ بیانی ہو — ان کے حال کے سوال کا جواب جو اللہ کی آیات میں نہیں جھگڑتے۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:r3', 'phrase', 'QR:PH:40:7:s1:p1', 'qul_jadwal_irab_quran;qul_irab_quran_daas;qul_irab_muyassar;tibyan_ukbari_irab', 'jumhur', 'irab', '«Those who bear the Throne» is the subject, «and those around it» joined to it, «they glorify» its predicate.', '«الذين يحملون العرش» مبتدأ، و«من حوله» معطوف عليه، وجملة «يسبحون» خبره.', 0, 0, 1, 4, NULL, '{"ar": "«الذين يحملون العرش» مبتدأ، و«من حوله» معطوف عليه، وجملة «يسبحون» خبره.", "en": "«Those who bear the Throne» is the subject, «and those around it» joined to it, «they glorify» its predicate.", "ur": "«الذین یحملون العرش» مبتدا ہے، «ومن حولہ» اس پر معطوف، اور «یسبحون» اس کی خبر۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:r4', 'phrase', 'QR:PH:40:7:s1:p4', 'qul_jadwal_irab_quran;qul_irab_muyassar;ibn_ashur', 'jumhur', 'irab', '«bi-ḥamdi rabbihim» belongs to an omitted ḥāl of the subject — accompanied by praise; the bāʾ is of accompaniment.', '«بحمد ربهم» متعلق بمحذوف حال من فاعل «يسبحون»: ملابسين للحمد، والباء للملابسة.', 0, 0, 1, 3, NULL, '{"ar": "«بحمد ربهم» متعلق بمحذوف حال من فاعل «يسبحون»: ملابسين للحمد، والباء للملابسة.", "en": "«bi-ḥamdi rabbihim» belongs to an omitted ḥāl of the subject — accompanied by praise; the bāʾ is of accompaniment.", "ur": "«بحمد ربہم» فاعلِ «یسبحون» کے محذوف حال سے متعلق ہے — حمد کے ساتھ؛ باء ملابست کی ہے۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:r5', 'phrase', 'QR:PH:40:7:s1:p4', 'qul_irab_quran_daas', 'minority', 'irab', '«bi-ḥamdi» attaches to «yusabbiḥūna» directly (al-Daʿʿās).', '«بحمد» متعلقان بـ«يسبحون» مباشرة (دعاس).', 1, 0, 0, 1, NULL, '{"ar": "«بحمد» متعلقان بـ«يسبحون» مباشرة (دعاس).", "en": "«bi-ḥamdi» attaches to «yusabbiḥūna» directly (al-Daʿʿās).", "ur": "«بحمد» براہِ راست «یسبحون» سے متعلق ہے (دعاس)۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:r6', 'phrase', 'QR:PH:40:7:s1:p6', 'qul_jadwal_irab_quran;qul_irab_muyassar;tibyan_ukbari_irab;tabari;zamakhshari', 'jumhur', 'irab', 'After «they ask forgiveness for the believers» a «they say» is omitted; its clause is a ḥāl of the subject of «yastaghfirūna».', 'بعد «يستغفرون للذين آمنوا» قول محذوف «يقولون»، جملته حال من فاعل «يستغفرون».', 0, 0, 1, 5, 'al-Ṭabarī supplies the omitted «يقولون»; al-Zamakhsharī gives the ḥāl as his second option. Rule: dropping al-qawl is common (Mughnī p.827).', '{"ar": "بعد «يستغفرون للذين آمنوا» قول محذوف «يقولون»، جملته حال من فاعل «يستغفرون».", "en": "After «they ask forgiveness for the believers» a «they say» is omitted; its clause is a ḥāl of the subject of «yastaghfirūna».", "ur": "«یستغفرون للذین آمنوا» کے بعد «یقولون» محذوف ہے، جس کا جملہ فاعلِ «یستغفرون» کا حال ہے۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:r7', 'phrase', 'QR:PH:40:7:s1:p6', 'zamakhshari;ibn_ashur', 'minority', 'irab', 'The omitted «they say» explains «yastaghfirūna», nominative like it (al-Zamakhsharī first); Ibn ʿĀshūr: «Our Lord, You encompass» explains «yastaghfirūna».', 'القول المحذوف بيان لـ«يستغفرون» مرفوع المحل مثله (الزمخشري)؛ وابن عاشور: جملة «ربنا وسعت» مبيّنة لـ«يستغفرون».', 1, 1, 0, 2, NULL, '{"ar": "القول المحذوف بيان لـ«يستغفرون» مرفوع المحل مثله (الزمخشري)؛ وابن عاشور: جملة «ربنا وسعت» مبيّنة لـ«يستغفرون».", "en": "The omitted «they say» explains «yastaghfirūna», nominative like it (al-Zamakhsharī first); Ibn ʿĀshūr: «Our Lord, You encompass» explains «yastaghfirūna».", "ur": "محذوف قول «یستغفرون» کا بیان ہے، اسی کی طرح محلاً مرفوع (زمخشری کا پہلا قول)؛ ابن عاشور: «ربنا وسعت» «یستغفرون» کی وضاحت ہے۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:SR:40:7:s1:census', 'sentence', 'QR:SS:40:7:jadwal:s1', 'qul_jadwal_irab_quran;qul_irab_quran_daas;qul_irab_muyassar;tibyan_ukbari_irab;qul_irab_darwish;qul_dep_graphs', 'synthesis', 'irab', 'Census of the six registered iʿrāb sources: four parse the sentence (al-Jadwal, al-Daʿʿās, al-Muyassar, al-ʿUkbarī); two are silent (al-Darwīsh, whose grouped 40:7–9 entry begins at «innaka anta l-ʿazīzu l-ḥakīm» in 40:8; the dependency graphs, with no row).', 'حصر كتب الإعراب الستة المسجلة: أربعة تعرب الجملة (الجدول، دعاس، الميسر، العكبري)، وساكتان (الدرويش، إذ يبدأ إعرابه المجمّع ٤٠: ٧–٩ من «إنك أنت العزيز الحكيم» في ٤٠: ٨؛ والمخططات الاعتمادية، لا صف لها).', 0, 0, 0, 4, NULL, '{"ar": "حصر كتب الإعراب الستة المسجلة: أربعة تعرب الجملة (الجدول، دعاس، الميسر، العكبري)، وساكتان (الدرويش، إذ يبدأ إعرابه المجمّع ٤٠: ٧–٩ من «إنك أنت العزيز الحكيم» في ٤٠: ٨؛ والمخططات الاعتمادية، لا صف لها).", "en": "Census of the six registered iʿrāb sources: four parse the sentence (al-Jadwal, al-Daʿʿās, al-Muyassar, al-ʿUkbarī); two are silent (al-Darwīsh, whose grouped 40:7–9 entry begins at «innaka anta l-ʿazīzu l-ḥakīm» in 40:8; the dependency graphs, with no row).", "ur": "چھ رجسٹرڈ اعرابی مصادر کا جائزہ: چار اس جملے کا اعراب کرتے ہیں (الجدول، دعاس، المیسر، عکبری)؛ دو خاموش ہیں (درویش، جن کا ۴۰: ۷–۹ کا مجموعی اعراب ۴۰: ۸ کے «انک انت العزیز الحکیم» سے شروع ہوتا ہے؛ اور dependency graphs)۔"}', '2026-10-15 18:00:00', '2026-10-15 18:00:00');

