INSERT OR REPLACE INTO qr_ss_scope_grammar_link (id, scope_type, scope_id, lx_grammar_ref, application_note, gloss_json, created_at) VALUES
('QR:GR:40:7:s1:g1', 'sentence', 'QR:SS:40:7:jadwal:s1', 'GT:sentence_role:istinafiyya', 'The sentence resumes, with no place (al-Jadwal; Mughnī p.500).', '{"ar": "الجملة مستأنفة لا محل لها (الجدول؛ مغني اللبيب ص٥٠٠).", "en": "The sentence resumes, with no place (al-Jadwal; Mughnī p.500).", "ur": "جملہ مستانفہ، محل سے خالی (الجدول؛ مغنی اللبیب ص۵۰۰)۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g2', 'phrase', 'QR:PH:40:7:s1:p1', 'GT:irab_role:mubtada', '«alladhīna» with its relative clause is the subject.', '{"ar": "«الذين» وصلته المبتدأ.", "en": "«alladhīna» with its relative clause is the subject.", "ur": "«الذین» اپنے صلے سمیت مبتدا ہے۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g3', 'phrase', 'QR:PH:40:7:s1:p1', 'GT:irab_role:silat_mawsul', '«yaḥmilūna al-ʿarsh» and «āmanū» are relative clauses, with no place.', '{"ar": "«يحملون العرش» و«آمنوا» صلتان لا محل لهما.", "en": "«yaḥmilūna al-ʿarsh» and «āmanū» are relative clauses, with no place.", "ur": "«یحملون العرش» اور «آمنوا» صلے ہیں، محل سے خالی۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g4', 'phrase', 'QR:PH:40:7:s1:p2', 'GT:irab_role:maatuf', '«man ḥawlahu» is joined to the subject (Qaṭr p.283).', '{"ar": "«من حوله» معطوف على المبتدأ (قطر الندى ص٢٨٣).", "en": "«man ḥawlahu» is joined to the subject (Qaṭr p.283).", "ur": "«من حولہ» مبتدا پر معطوف ہے (قطر الندی ص۲۸۳)۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g5', 'phrase', 'QR:PH:40:7:s1:p2', 'GT:irab_role:zarf', '«ḥawlahu» is an adverb standing as the relative clause of «man».', '{"ar": "«حوله» ظرف متعلق بمحذوف صلة «مَن».", "en": "«ḥawlahu» is an adverb standing as the relative clause of «man».", "ur": "«حولہ» ظرف ہے جو «مَن» کے محذوف صلے سے متعلق ہے۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g6', 'phrase', 'QR:PH:40:7:s1:p3', 'GT:irab_role:khabar', 'The verbal clause «yusabbiḥūna» is the predicate, nominative.', '{"ar": "جملة «يسبحون» في محل رفع خبر.", "en": "The verbal clause «yusabbiḥūna» is the predicate, nominative.", "ur": "جملۂ «یسبحون» محلاً مرفوع خبر ہے۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g7', 'phrase', 'QR:PH:40:7:s1:p4', 'GT:irab_role:hal', '«bi-ḥamdi rabbihim» stands for a ḥāl of the subject of «yusabbiḥūna».', '{"ar": "«بحمد ربهم» متعلق بحال من فاعل «يسبحون».", "en": "«bi-ḥamdi rabbihim» stands for a ḥāl of the subject of «yusabbiḥūna».", "ur": "«بحمد ربہم» فاعلِ «یسبحون» کے حال سے متعلق ہے۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g8', 'phrase', 'QR:PH:40:7:s1:p5', 'GT:irab_role:maatuf', '«yuʾminūna bihi» and «yastaghfirūna» are joined to the predicate clause, nominative.', '{"ar": "«يؤمنون به» و«يستغفرون» معطوفتان على جملة الخبر في محل رفع.", "en": "«yuʾminūna bihi» and «yastaghfirūna» are joined to the predicate clause, nominative.", "ur": "«یؤمنون بہ» اور «یستغفرون» جملۂ خبر پر معطوف ہیں، محلاً مرفوع۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g9', 'phrase', 'QR:PH:40:7:s1:p7', 'GT:irab_role:mutaalliq', '«bihi» attaches to «yuʾminūna», «li-lladhīna» to «yastaghfirūna».', '{"ar": "«به» متعلق بـ«يؤمنون»، و«للذين» بـ«يستغفرون».", "en": "«bihi» attaches to «yuʾminūna», «li-lladhīna» to «yastaghfirūna».", "ur": "«بہ» «یؤمنون» سے اور «للذین» «یستغفرون» سے متعلق ہے۔"}', '2026-10-15 18:00:00'),
('QR:GR:40:7:s1:g10', 'phrase', 'QR:PH:40:7:s1:p1', 'GT:irab_role:maful_bih', '«al-ʿarsh» is the object of «yaḥmilūna»; the object of «yusabbiḥūna» is understood.', '{"ar": "«العرش» مفعول «يحملون»، ومفعول «يسبحون» محذوف.", "en": "«al-ʿarsh» is the object of «yaḥmilūna»; the object of «yusabbiḥūna» is understood.", "ur": "«العرش» «یحملون» کا مفعول ہے، اور «یسبحون» کا مفعول محذوف ہے۔"}', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_scope_balagha_link (id, scope_type, scope_id, lx_balagha_ref, balagha_category, rhetorical_effect, note_md, gloss_json, created_at) VALUES
('QR:BL:40:7:s1:b1', 'sentence', 'QR:SS:40:7:jadwal:s1', 'GT:balagha_maani:istinaf_bayani', 'mani', 'Ibn ʿĀshūr reads the sentence first as a fresh start (istiʾnāf ibtidāʾī) — the turn from the threat on the disbelievers to praise of the believers, a contrast of states and of speeches — and allows a clarifying resumption (bayānī).', 'Grounded: QR:EV:40:7:s1:ibn_ashur:1. Linked as the alternative; the primary reading is r1.', '{"ar": "ابن عاشور: استئناف ابتدائي للانتقال من الوعيد إلى الثناء على المؤمنين، ويجوز أن يكون بيانيًا.", "en": "Ibn ʿĀshūr: a fresh start turning from threat to praise; possibly a clarifying resumption.", "ur": "ابن عاشور: وعید سے مومنوں کی تعریف کی طرف نیا آغاز؛ ممکن ہے استینافِ بیانی ہو۔"}', '2026-10-15 18:00:00'),
('QR:BL:40:7:s1:b2', 'phrase', 'QR:PH:40:7:s1:p3', 'GT:balagha_maani:hadhf_maful', 'mani', 'The object of «yusabbiḥūna» is left out because «bi-ḥamdi rabbihim» shows it (Ibn ʿĀshūr).', 'Grounded: QR:EV:40:7:s1:ibn_ashur:1.', '{"ar": "حُذف مفعول «يسبحون» لدلالة المتعلق «بحمد ربهم» عليه (ابن عاشور).", "en": "The object of «they glorify» is dropped, since «with their Lord''s praise» shows it (Ibn ʿĀshūr).", "ur": "«یسبحون» کا مفعول محذوف ہے کیونکہ «بحمد ربہم» اس پر دلالت کرتا ہے (ابن عاشور)۔"}', '2026-10-15 18:00:00'),
('QR:BL:40:7:s1:b3', 'phrase', 'QR:PH:40:7:s1:p3', 'GT:balagha_maani:mudari_istimrar', 'mani', 'The present tenses «yusabbiḥūna, yuʾminūna, yastaghfirūna» mark renewal and repetition — something the angels keep doing now, in this world (Ibn ʿĀshūr).', 'Grounded: QR:EV:40:7:s1:ibn_ashur:1.', '{"ar": "صيغة المضارع في «يسبحون، يؤمنون، يستغفرون» لتجدد ذلك وتكرره (ابن عاشور).", "en": "The present tense marks renewal and repetition (Ibn ʿĀshūr).", "ur": "مضارع کے صیغے تجدد اور تکرار کے لیے ہیں (ابن عاشور)۔"}', '2026-10-15 18:00:00'),
('QR:BL:40:7:s1:b4', 'phrase', 'QR:PH:40:7:s1:p5', 'GT:balagha_bayan:tarid', 'bayan', '«wa-yuʾminūna bihi», obvious of angels, is said to honour faith as the state of the noblest creatures and to reproach the idolaters obliquely (Ibn ʿĀshūr); to show the honour of faith (al-Zamakhsharī).', 'Grounded: QR:EV:40:7:s1:ibn_ashur:1, QR:EV:40:7:s1:zamakhshari:1.', '{"ar": "الإخبار بأنهم يؤمنون مع كونه معلومًا للتنويه بشأن الإيمان والتعريض بالمشركين (ابن عاشور).", "en": "Saying they believe, though known, honours faith and reproaches the idolaters obliquely (Ibn ʿĀshūr).", "ur": "یہ بتانا کہ وہ ایمان رکھتے ہیں، حالانکہ معلوم ہے، ایمان کی شان بڑھانے اور مشرکوں پر تعریض کے لیے ہے (ابن عاشور)۔"}', '2026-10-15 18:00:00'),
('QR:BL:40:7:s1:b5', 'phrase', 'QR:PH:40:7:s1:p6', 'GT:balagha_badi:muraat_nazir', 'badi', '«yuʾminūna bihi wa-yastaghfirūna li-lladhīna āmanū»: believers asking forgiveness for those of their own state — shared faith binds angel and man (al-Zamakhsharī).', 'Grounded: QR:EV:40:7:s1:zamakhshari:1.', '{"ar": "روعي التناسب في «يؤمنون به ويستغفرون للذين آمنوا»: يستغفرون لمن في مثل حالهم (الزمخشري).", "en": "A congruence: those who believe ask forgiveness for those who believe (al-Zamakhsharī).", "ur": "تناسب: ایمان والے ایمان والوں کے لیے مغفرت مانگتے ہیں (زمخشری)۔"}', '2026-10-15 18:00:00'),
('QR:BL:40:7:s1:b6', 'phrase', 'QR:PH:40:7:s1:p6', 'GT:balagha_maani:hadhf_qawl', 'mani', 'The verb of speaking is dropped and the prayer follows at once, so the angels'' words are heard as they say them (al-Ṭabarī, al-Zamakhsharī, Ibn ʿĀshūr; Mughnī p.827: dropping al-qawl is common).', 'Grounded: QR:EV:40:7:s1:tabari:1, :zamakhshari:1, :ibn_ashur:1.', '{"ar": "حذف القول استغناءً بالمقول، فيُسمع دعاء الملائكة كما يقولونه (الطبري والزمخشري وابن عاشور).", "en": "The verb of speaking is dropped for the speech itself, so the angels'' prayer is heard as they say it.", "ur": "قول کو مقول پر اکتفا کر کے حذف کیا گیا، تاکہ فرشتوں کی دعا ویسے ہی سنائی دے جیسے وہ کہتے ہیں۔"}', '2026-10-15 18:00:00'),
('QR:BLK:QR:SS:40:7:jadwal:s1', 'sentence', 'QR:SS:40:7:jadwal:s1', 'GT:kalam_kind:khabar_ibtidai', 'mani', 'A plain assertion: no emphasizer, a report of what the angels do, told to the believers and the Prophet who do not deny it (al-Qazwīnī, al-Īḍāḥ 1/69).', 'Emphasizers on the main assertion: none. Rule: qazwini_idah 1/69.', '{"ar": "خبر ابتدائي: لا مؤكد، إخبار عن فعل الملائكة لمن لا ينكره (الإيضاح ١/٦٩).", "en": "A plain assertion, unemphasized, to listeners who do not deny it (al-Īḍāḥ 1/69).", "ur": "خبرِ ابتدائی: کوئی تاکید نہیں، ان سامعین کو جو انکار نہیں کرتے (الایضاح ۱/۶۹)۔"}', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_scope_nuance (id, scope_type, scope_id, nuance_type, nuance_text, nuance_text_ar, gloss_json, source_basis, source_ref, created_at, updated_at) VALUES
('QR:NU:40:7:s1:n1', 'sentence', 'QR:SS:40:7:jadwal:s1', 'discourse', 'Their glorifying and believing are mentioned to prepare the real news — that they ask forgiveness for the believers — since a plea from those whose habit is glorification and whose state is faith is answered (Ibn ʿĀshūr).', 'الإخبار بأنهم يسبحون ويؤمنون توطئة للمقصود وهو استغفارهم للذين آمنوا، تحقيقًا لاستجابته لصدوره ممن دأبهم التسبيح (ابن عاشور).', '{"ar": "الإخبار بأنهم يسبحون ويؤمنون توطئة للمقصود وهو استغفارهم للذين آمنوا، تحقيقًا لاستجابته لصدوره ممن دأبهم التسبيح (ابن عاشور).", "en": "Their glorifying and believing are mentioned to prepare the real news — that they ask forgiveness for the believers — since a plea from those whose habit is glorification and whose state is faith is answered (Ibn ʿĀshūr).", "ur": "ان کی تسبیح اور ایمان کا ذکر اصل خبر کی تمہید ہے — یعنی مومنوں کے لیے ان کا استغفار — کہ تسبیح جن کی عادت ہو ان کی دعا قبول ہوتی ہے (ابن عاشور)۔"}', 'tafsir', 'ibn_ashur', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:NU:40:7:s1:n2', 'sentence', 'QR:SS:40:7:jadwal:s1', 'referent', '«Those who bear the Throne» are the angels charged with raising it (Ibn ʿĀshūr) — four today and eight on the Day (Ibn Kathīr, citing al-Ḥāqqa 17); «those around it» are the angels who encircle it (Ibn ʿĀshūr, al-Ṭabarī), the karūbiyyūn (Ibn Kathīr). Ibn ʿĀshūr: no need to delve into their number.', '«الذين يحملون العرش» الموكلون برفعه (ابن عاشور)، وهم اليوم أربعة ويوم القيامة ثمانية (ابن كثير)؛ و«من حوله» ملائكة تحفّ بالعرش (ابن عاشور والطبري)، الكروبيون (ابن كثير). ولا حاجة إلى الخوض في عددهم (ابن عاشور).', '{"ar": "«الذين يحملون العرش» الموكلون برفعه (ابن عاشور)، وهم اليوم أربعة ويوم القيامة ثمانية (ابن كثير)؛ و«من حوله» ملائكة تحفّ بالعرش (ابن عاشور والطبري)، الكروبيون (ابن كثير). ولا حاجة إلى الخوض في عددهم (ابن عاشور).", "en": "«Those who bear the Throne» are the angels charged with raising it (Ibn ʿĀshūr) — four today and eight on the Day (Ibn Kathīr, citing al-Ḥāqqa 17); «those around it» are the angels who encircle it (Ibn ʿĀshūr, al-Ṭabarī), the karūbiyyūn (Ibn Kathīr). Ibn ʿĀshūr: no need to delve into their number.", "ur": "«الذین یحملون العرش» وہ فرشتے ہیں جو عرش اٹھانے پر مامور ہیں (ابن عاشور) — آج چار اور قیامت کے دن آٹھ (ابن کثیر)؛ «من حولہ» وہ جو عرش کو گھیرے ہوئے ہیں (ابن عاشور، طبری)، کروبیین (ابن کثیر)۔ ان کی تعداد میں پڑنے کی ضرورت نہیں (ابن عاشور)۔"}', 'tafsir', 'ibn_ashur;ibn_kathir;tabari', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:NU:40:7:s1:n3', 'sentence', 'QR:SS:40:7:jadwal:s1', 'lexical', 'Glorifying denies every flaw and praising affirms every perfection (Ibn Kathīr); glorifying points to majesty and praising to generosity (al-Rāzī). Reverence for God''s command comes before compassion for His creatures — glorifying and believing, then asking forgiveness (al-Rāzī).', 'التسبيح لنفي النقائص والتحميد لإثبات صفات المدح (ابن كثير)؛ التسبيح إشارة إلى الجلال والتحميد إلى الإكرام، والتعظيم لأمر الله مقدّم على الشفقة على خلقه (الرازي).', '{"ar": "التسبيح لنفي النقائص والتحميد لإثبات صفات المدح (ابن كثير)؛ التسبيح إشارة إلى الجلال والتحميد إلى الإكرام، والتعظيم لأمر الله مقدّم على الشفقة على خلقه (الرازي).", "en": "Glorifying denies every flaw and praising affirms every perfection (Ibn Kathīr); glorifying points to majesty and praising to generosity (al-Rāzī). Reverence for God''s command comes before compassion for His creatures — glorifying and believing, then asking forgiveness (al-Rāzī).", "ur": "تسبیح ہر نقص کی نفی ہے اور تحمید ہر کمال کا اثبات (ابن کثیر)؛ تسبیح جلال کی طرف اور تحمید اکرام کی طرف اشارہ ہے، اور اللہ کے حکم کی تعظیم اس کی مخلوق پر شفقت سے مقدم ہے (رازی)۔"}', 'tafsir', 'ibn_kathir;razi', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:NU:40:7:s1:n4', 'sentence', 'QR:SS:40:7:jadwal:s1', 'theology', 'Al-Rāzī: the bearer of the Throne bears what is on it, so God is not on the Throne. Al-Zamakhsharī: «they believe in Him» shows the bearers do not see Him (al-Rāzī praises the point); Ibn al-Munayyir rebuts it — belief is assent and does not require its object to be absent.', 'الرازي: حامل العرش حامل لما فيه، فإله العالم متعالٍ عن العرش. الزمخشري: «ويؤمنون به» دليل على أنهم لا يشاهدونه (وأثنى عليه الرازي)؛ وردّه ابن المنيّر بأن الإيمان تصديق لا يشترط فيه غيبة المصدَّق به.', '{"ar": "الرازي: حامل العرش حامل لما فيه، فإله العالم متعالٍ عن العرش. الزمخشري: «ويؤمنون به» دليل على أنهم لا يشاهدونه (وأثنى عليه الرازي)؛ وردّه ابن المنيّر بأن الإيمان تصديق لا يشترط فيه غيبة المصدَّق به.", "en": "Al-Rāzī: the bearer of the Throne bears what is on it, so God is not on the Throne. Al-Zamakhsharī: «they believe in Him» shows the bearers do not see Him (al-Rāzī praises the point); Ibn al-Munayyir rebuts it — belief is assent and does not require its object to be absent.", "ur": "رازی: عرش اٹھانے والا اس پر موجود چیز کو اٹھاتا ہے، اس لیے اللہ عرش سے بلند ہے۔ زمخشری: «ویؤمنون بہ» بتاتا ہے کہ وہ اسے دیکھتے نہیں (رازی نے اسے سراہا)؛ ابن المنیر نے رد کیا کہ ایمان تصدیق ہے، اس کے لیے غیب ہونا شرط نہیں۔"}', 'tafsir', 'razi;zamakhshari', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:NU:40:7:s1:n5', 'sentence', 'QR:SS:40:7:jadwal:s1', 'referent', '«Those who believe» are the believers in Muḥammad, though the words fit every believer (Ibn ʿĀshūr); «the people of lā ilāha illā Allāh» (Qatāda, in al-Ṭabarī).', '«الذين آمنوا» المؤمنون بمحمد ﷺ وإن صلح لكل المؤمنين (ابن عاشور)؛ «لأهل لا إله إلا الله» (قتادة عند الطبري).', '{"ar": "«الذين آمنوا» المؤمنون بمحمد ﷺ وإن صلح لكل المؤمنين (ابن عاشور)؛ «لأهل لا إله إلا الله» (قتادة عند الطبري).", "en": "«Those who believe» are the believers in Muḥammad, though the words fit every believer (Ibn ʿĀshūr); «the people of lā ilāha illā Allāh» (Qatāda, in al-Ṭabarī).", "ur": "«الذین آمنوا» محمد ﷺ پر ایمان لانے والے ہیں، اگرچہ لفظ ہر مومن پر صادق ہے (ابن عاشور)؛ «لا الٰہ الا اللہ والوں کے لیے» (قتادہ، طبری میں)۔"}', 'tafsir', 'ibn_ashur;tabari', '2026-10-15 18:00:00', '2026-10-15 18:00:00'),
('QR:NU:40:7:s1:n6', 'sentence', 'QR:SS:40:7:jadwal:s1', 'theme', 'Shared faith calls for sincere care across every distance of kind and place: there is no likeness between angel and man, heavenly and earthly, until faith joins them — then those around the Throne ask forgiveness for those on the earth (al-Zamakhsharī).', 'الاشتراك في الإيمان أدعى شيء إلى النصيحة وإمحاض الشفقة وإن تفاوتت الأجناس وتباعدت الأماكن، حتى استغفر من حول العرش لمن فوق الأرض (الزمخشري).', '{"ar": "الاشتراك في الإيمان أدعى شيء إلى النصيحة وإمحاض الشفقة وإن تفاوتت الأجناس وتباعدت الأماكن، حتى استغفر من حول العرش لمن فوق الأرض (الزمخشري).", "en": "Shared faith calls for sincere care across every distance of kind and place: there is no likeness between angel and man, heavenly and earthly, until faith joins them — then those around the Throne ask forgiveness for those on the earth (al-Zamakhsharī).", "ur": "ایمان میں شرکت خیر خواہی اور خالص شفقت کی سب سے بڑی داعی ہے، چاہے جنسیں مختلف اور مقامات دور ہوں — یہاں تک کہ عرش کے گرد والے زمین والوں کے لیے مغفرت مانگتے ہیں (زمخشری)۔"}', 'tafsir', 'zamakhshari', '2026-10-15 18:00:00', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_ellipsis_event (id, sentence_id, scope_type, scope_id, ellipsis_type, lx_ellipsis_ref, elided_element, rhetorical_effect, note_md, source_basis, source_ref, created_at) VALUES
('QR:EL:40:7:s1:maful', 'QR:SS:40:7:jadwal:s1', 'phrase', 'QR:PH:40:7:s1:p3', 'maful_mahdhuf', 'GT:balagha_maani:hadhf_maful', 'اللَّهَ', 'The object of «they glorify» is understood from «with their Lord''s praise».', 'ابن عاشور: حذف مفعول يسبحون لدلالة المتعلق به عليه.', 'tafsir', 'ibn_ashur', '2026-10-15 18:00:00'),
('QR:EL:40:7:s1:qawl', 'QR:SS:40:7:jadwal:s1', 'phrase', 'QR:PH:40:7:s1:p6', 'qawl_mahdhuf', 'GT:balagha_maani:hadhf_qawl', 'يَقُولُونَ', 'The verb of speaking is understood; the prayer that follows is its speech.', 'الطبري والعكبري والميسر والجدول والزمخشري وابن عاشور؛ وحذف القول كثير (مغني اللبيب ص٨٢٧).', 'tafsir;irab', 'tabari;tibyan_ukbari_irab;qul_irab_muyassar;qul_jadwal_irab_quran;zamakhshari;ibn_ashur', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_discourse_note (id, scope_type, scope_id, surah, marker, question_ar, verdict_ar, source_basis, status, created_at) VALUES
('QR:DN:40:7:s1a', 'phrase', 'QR:PH:40:7:s1:p6', 40, '¹', 'ما محلّ القول المحذوف «يقولون» بعد «ويستغفرون للذين آمنوا»؟', 'المرجّح: حال من فاعل «يستغفرون» (الجدول والميسر والعكبري، والزمخشري وجهًا)؛ والزمخشري يقدّم أنه بيان لـ«يستغفرون» مرفوع المحل، وابن عاشور يجعل الدعاء مبيّنًا له.', 'irab;tafsir', 'raw', '2026-10-15 18:00:00'),
('QR:DN:40:7:s1b', 'phrase', 'QR:PH:40:7:s1:p5', 40, '²', 'ما فائدة «ويؤمنون به» والملائكة مؤمنون بداهة؟', 'التنويه بشرف الإيمان والتعريض بالمشركين (ابن عاشور والزمخشري)؛ وزاد الزمخشري أنهم لا يشاهدونه، وردّه ابن المنيّر.', 'tafsir', 'raw', '2026-10-15 18:00:00');

