('QR:DC:40:7:s1b:1', 'QR:DN:40:7:s1b', NULL, 1, 'التنويه بالإيمان والتعريض بالمشركين', 'ابن عاشور · الزمخشري', 'tafsir', 'مرجّح', 'raw', '2026-10-15 18:00:00'),
