INSERT OR REPLACE INTO qr_ss_scope_link (id, from_scope_type, from_scope_id, to_scope_type, to_scope_id, relation_type, note_md, source_basis, gloss_json, created_at) VALUES
('QR:SREL:40:7:s1:1', 'sentence', 'QR:SS:40:7:jadwal:s1', 'sentence', 'QR:SS:40:7:s2', 'qawl_muqawwal', 'الدعاء «ربنا وسعت…» مقول القول المحذوف «يقولون» (الجدول والميسر والعكبري والطبري)، مبيّن لـ«يستغفرون» (ابن عاشور).', 'qul_jadwal_irab_quran;qul_irab_muyassar;tibyan_ukbari_irab;tabari;ibn_ashur', '{"ar": "«ربنا وسعت…» مقول القول المحذوف بعد «يستغفرون».", "en": "«Our Lord, You encompass…» is the speech of the «they say» omitted after «they ask forgiveness».", "ur": "«ربنا وسعت…» «یستغفرون» کے بعد محذوف قول کا مقول ہے۔"}', '2026-10-15 18:00:00'),
('QR:SREL:40:7:s1:2', 'sentence', 'QR:SS:40:7:jadwal:s1', 'sentence', 'QR:SS:40:6:jadwal:s1', 'muqabala', 'الانتقال من الوعيد المؤذن بذم الذين كفروا إلى الثناء على المؤمنين، والمناسبة المضادة بين الحالين والمقالين (ابن عاشور).', 'ibn_ashur', '{"ar": "مقابلة: بعد أن حقّت كلمة العذاب على الكافرين، يذكر استغفار الملائكة للمؤمنين (ابن عاشور).", "en": "A contrast: after the word of punishment came due on the disbelievers, the angels'' plea for the believers (Ibn ʿĀshūr).", "ur": "مقابلہ: کافروں پر عذاب کا کلمہ ثابت ہونے کے بعد مومنوں کے لیے فرشتوں کا استغفار (ابن عاشور)۔"}', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_translation_unit (id, scope_type, scope_id, surah, ayah_from, ayah_to, seq, structural_literal_en, fluent_en, fluent_ar, decision_note_ar, synthesis_md, gloss_json, status, reading_ref, rejected_readings_json, created_at, updated_at) VALUES
('QR:TL:40:7:s1', 'sentence', 'QR:SS:40:7:jadwal:s1', 40, 7, 7, 1, 'Those who carry the Throne, and whoever is around it, glorify [Him] with the praise of their Lord, and believe in Him, and ask forgiveness for those who have believed — [saying]:', 'Those who bear the Throne, and those around it, glorify their Lord with praise, believe in Him, and ask forgiveness for the believers, saying:', 'الملائكة الذين يحملون العرش ومن يحفّ به يسبّحون الله حامدين له، ويؤمنون به، ويستغفرون للمؤمنين قائلين:', 'يُصرَّح بالقول المحذوف «saying» لأن الإنجليزية لا تحتمل الانتقال إلى المقول بلا فعل قول.', 'The subject comes first as in the Arabic; the predicate keeps its three present tenses. What English loses: (1) the renewal the Arabic present carries — English simple present reads as habit, close but flatter; (2) the dropped object of «glorify», which English must name («their Lord») where Arabic lets «with their Lord''s praise» imply it; (3) the omitted «they say» — English needs «saying», so the Arabic''s step straight into the angels'' words is softened; (4) «those who have believed» (a past) becomes «the believers», a state.', '{"ar": "ترجمة تحفظ ترتيب المبتدأ والخبر؛ وتفوت الإنجليزيةَ دلالةُ المضارع على التجدد، وحذفُ المفعول، وحذفُ القول.", "en": "The rendering keeps subject before predicate; English loses the renewal of the present, the dropped object, and the dropped verb of speaking.", "ur": "ترجمہ مبتدا و خبر کی ترتیب برقرار رکھتا ہے؛ انگریزی میں مضارع کا تجدد، محذوف مفعول اور محذوف قول فوت ہو جاتے ہیں۔"}', 'live', 'QR:SR:40:7:s1:r6', '[{"reading_ref": "QR:SR:40:7:s1:r7", "en": "…and ask forgiveness for the believers — that is, they say:", "why": "The explanatory reading (al-Zamakhsharī, Ibn ʿĀshūr) is the minority; «saying» renders the ḥāl."}]', '2026-10-15 18:00:00', '2026-10-15 18:00:00');

INSERT OR REPLACE INTO qr_ss_translation_decision (id, unit_id, surah, ayah, step_seq, target_span_ar, rendered_json, driver_kind, driver_ref, rationale_json, status, created_at) VALUES
('QR:TD:40:7:s1:d1', 'QR:TL:40:7:s1', 40, 7, 1, 'وَمَنْ حَوْلَهُ', '{"ar": "ومن يحفّ بالعرش", "en": "and those around it", "ur": "اور جو اس کے گرد ہیں"}', 'nuance', 'QR:NU:40:7:s1:n2', '{"ar": "«من» للعاقل الجمع، فتُترجم those.", "en": "«man» stands for a plural of persons, so «those»."}', 'live', '2026-10-15 18:00:00'),
('QR:TD:40:7:s1:d2', 'QR:TL:40:7:s1', 40, 7, 2, 'يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ', '{"ar": "يسبحون الله حامدين", "en": "glorify their Lord with praise", "ur": "اپنے رب کی حمد کے ساتھ تسبیح کرتے ہیں"}', 'reading', 'QR:SR:40:7:s1:r4', '{"ar": "الجار والمجرور حال: «مع الحمد»، والمفعول المحذوف يُذكر «their Lord».", "en": "The phrase is a ḥāl — «with praise» — and the dropped object is named, «their Lord»."}', 'live', '2026-10-15 18:00:00'),
('QR:TD:40:7:s1:d3', 'QR:TL:40:7:s1', 40, 7, 3, 'يُسَبِّحُونَ … وَيُؤْمِنُونَ … وَيَسْتَغْفِرُونَ', '{"ar": "المضارع", "en": "glorify … believe … ask", "ur": "تسبیح کرتے … ایمان رکھتے … مانگتے ہیں"}', 'balagha', 'QR:BL:40:7:s1:b3', '{"ar": "المضارع للتجدد، والمضارع البسيط في الإنجليزية يحمل العادة.", "en": "The present marks renewal; the English simple present carries the habit."}', 'live', '2026-10-15 18:00:00'),
('QR:TD:40:7:s1:d4', 'QR:TL:40:7:s1', 40, 7, 4, 'وَيُؤْمِنُونَ بِهِ', '{"ar": "ويؤمنون به", "en": "believe in Him", "ur": "اس پر ایمان رکھتے ہیں"}', 'balagha', 'QR:BL:40:7:s1:b4', '{"ar": "يُبقى مع وضوحه لأنه للتنويه بالإيمان والتعريض.", "en": "Kept though obvious: it honours faith and reproaches by implication."}', 'live', '2026-10-15 18:00:00'),
('QR:TD:40:7:s1:d5', 'QR:TL:40:7:s1', 40, 7, 5, 'لِلَّذِينَ آمَنُوا', '{"ar": "للمؤمنين", "en": "for the believers", "ur": "ایمان والوں کے لیے"}', 'nuance', 'QR:NU:40:7:s1:n5', '{"ar": "الماضي في الصلة صفة ثابتة، فتُترجم اسمًا.", "en": "The past in the relative clause is a settled description, so a noun."}', 'live', '2026-10-15 18:00:00'),
('QR:TD:40:7:s1:d6', 'QR:TL:40:7:s1', 40, 7, 6, '(يَقُولُونَ)', '{"ar": "قائلين", "en": "saying:", "ur": "یہ کہتے ہوئے:"}', 'reading', 'QR:SR:40:7:s1:r6', '{"ar": "يُصرَّح بالقول المحذوف حالًا: saying.", "en": "The omitted verb of speaking is supplied as a ḥāl: «saying»."}', 'live', '2026-10-15 18:00:00');
